-- Migration: actors table + seed 200 actors
-- Sprint 24: Actor Library

-- ── Table ────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS actors (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name            text NOT NULL,
  slug            text NOT NULL UNIQUE,
  gender          text CHECK (gender IN ('female', 'male')),
  age             integer,
  age_range       text CHECK (age_range IN ('18-25', '26-35', '36-50', '51+')),
  nationality     text,
  style           text,
  actor_type      text CHECK (actor_type IN ('Young Adult', 'Professional', 'Mom', 'Elder', 'Casual')),
  portrait_url    text,
  base_clips      jsonb DEFAULT '[]',
  lip_sync_engine text NOT NULL DEFAULT 'aurora'
    CHECK (lip_sync_engine IN ('aurora', 'kling-avatar', 'synclabs')),
  voice_id        text,
  voice_gender    text CHECK (voice_gender IN ('female', 'male')),
  status          text DEFAULT 'active' CHECK (status IN ('active', 'pending', 'inactive')),
  created_at      timestamptz DEFAULT now(),
  updated_at      timestamptz DEFAULT now()
);

-- ── Indexes ──────────────────────────────────────────────────────────────────

CREATE INDEX IF NOT EXISTS idx_actors_gender ON actors (gender) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_actors_age_range ON actors (age_range) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_actors_actor_type ON actors (actor_type) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_actors_slug ON actors (slug);

-- ── RLS ──────────────────────────────────────────────────────────────────────

ALTER TABLE actors ENABLE ROW LEVEL SECURITY;

CREATE POLICY "actors_public_read" ON actors
  FOR SELECT USING (status = 'active');

CREATE POLICY "actors_service_role_all" ON actors
  FOR ALL USING (auth.role() = 'service_role');

